#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int req1 = 0, req2 = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            req1++;
        } else {
            req2++;
        }
    }

    int p, m;
    scanf("%d", &p);
    scanf("%d", &m);

    if (p >= req1 && m >= req2) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
